// 文字表記（和語・訓読み：動詞40／形容詞15／名詞15）
Bank.group('write-a', '文字表記', [
  // ── 動詞 ──
  ['トラックが工事の資材を【はこんで】きた。', '運んで', '連んで', '遅んで', '達んで', '搬運物品用「運ぶ」，部首是「辶」加「軍」。「連」「遅」「達」雖然都有「辶」，但沒有搬運的意思。'],
  ['道で百円玉を【ひろった】。', '拾った', '捨った', '抱った', '持った', '撿起東西用「拾う」。「捨てる」是丟棄，字形相近但意思相反。'],
  ['先生の言葉を、そのまま母に【つたえた】。', '伝えた', '転えた', '広えた', '送えた', '轉達話語用「伝える」。日文新字體寫作「伝」，不是繁體的「傳」；「転」是「轉」，意思不同。'],
  ['お客さんが来る前に、部屋を【かたづけた】。', '片付けた', '方付けた', '片着けた', '片置けた', '「片付ける」指把東西收拾整齊，漢字是「片」加「付」。「着」「置」雖然看似合理，但不是慣用寫法。'],
  ['趣味で古い切手を【あつめて】いる。', '集めて', '求めて', '会めて', '招めて', '把東西聚在一起用「集める」。「求める」讀作「もとめる」，意思是尋求。'],
  ['週に二回、スポーツクラブに【かよって】いる。', '通って', '運って', '週って', '道って', '定期往返某處用「通う」，部首是「辶」，與「道」「週」同樣形近。'],
  ['山の中で道に【まよって】しまった。', '迷って', '述って', '送って', '追って', '搞不清方向用「迷う」。「送って」讀作「おくって」，「追って」讀作「おって」。'],
  ['急に大きな音がして、とても【おどろいた】。', '驚いた', '警いた', '敬いた', '築いた', '嚇一跳用「驚く」，字下半是「馬」。「警」「敬」上半部相似，但意思與讀音都不同。'],
  ['参加者の人数を【かぞえた】。', '数えた', '教えた', '整えた', '算えた', '計算數量用「数える」，日文新字體是「数」。「教える」讀作「おしえる」，「整える」讀作「ととのえる」。'],
  ['ベランダでミニトマトを【そだてて】いる。', '育てて', '背てて', '肯てて', '養てて', '栽培植物、養育小孩用「育てる」，「育」的下半部是「月」。「養」雖然也有養育之意，但並沒有「養てる」這種說法。'],
  ['強い風で、道の木が【たおれた】。', '倒れた', '到れた', '例れた', '側れた', '東西倒下用「倒れる」，「倒」是「亻」加「到」。「到」「例」字形相近，容易寫錯。'],
  ['うっかり携帯電話を床に【おとして】しまった。', '落として', '絡として', '略として', '格として', '把東西掉到地上用「落とす」。「絡」「略」「格」都和「落」一樣含有「各」的部件，字形相近，但不是此詞的寫法。'],
  ['大事な約束なのに、日にちを【わすれて】いた。', '忘れて', '忙れて', '望れて', '志れて', '遺忘用「忘れる」，是「亡」加「心」。「忙」是「忄」加「亡」，用於「忙しい（いそがしい）」。'],
  ['新しい単語を毎日十個【おぼえる】。', '覚える', '見える', '学える', '習える', '記住事物用「覚える」，新字體是「覚」，不是繁體的「覺」。「見える」讀作「みえる」，意思是看得見。'],
  ['空港まで、遠くから来た友人を【むかえ】に行く。', '迎え', '迫え', '近え', '送え', '前往接人用「迎える」，名詞化為「迎え」。「迫」「近」字形相近但意思不同；「送」是送行，意思相反。'],
  ['二つの店の値段を【くらべて】から買うことにした。', '比べて', '北べて', '化べて', '並べて', '比較用「比べる」，字形像兩個「ヒ」並排。「並べる」讀作「ならべる」，是排列。'],
  ['コーヒーが【さめて】しまったので、温め直した。', '冷めて', '令めて', '冬めて', '寒めて', '熱的東西變涼用「冷める」，部首是「冫」。「令」「冬」字形相近；「寒」意思相近，但沒有這個搭配。'],
  ['子どもがおもちゃを【こわして】しまった。', '壊して', '懐して', '壌して', '環して', '弄壞東西用「壊す」。日文新字體「壊」，與繁體的「壞」寫法不同；「懐」「壌」字形相近。'],
  ['机を窓の近くに【うつした】。', '移した', '写した', '映した', '寄した', '移動位置用「移す」。「写す」是抄寫或拍攝，「映す」是把影像映出，都不能用來搬桌子。'],
  ['この料金には、税金も【ふくまれて】いる。', '含まれて', '今まれて', '舎まれて', '吟まれて', '包含在內用「含む」，是「今」加「口」。「今」「舎」「吟」只是形近的字。'],
  ['お金が【たりない】ので、安いほうを買った。', '足りない', '定りない', '満りない', '充りない', '數量夠用寫作「足りる」，否定是「足りない」。「満」「充」雖有充足之意，但並無此寫法。'],
  ['ご飯が【あまった】ので、おにぎりにした。', '余った', '除った', '徐った', '残った', '剩下用「余る」。「除」「徐」字形相近；「残る」讀作「のこる」，雖然意思相近，但讀音不同。'],
  ['スープに塩を少し【くわえた】。', '加えた', '力えた', '架えた', '賀えた', '添加東西用「加える」，由「力」與「口」組成。「賀」下面有「貝」，字形相近。'],
  ['最近、外国人の観光客が【ふえた】。', '増えた', '憎えた', '贈えた', '僧えた', '數量變多用「増える」。日文新字體是「増」，右半部上方寫作「ソ」，繁體則寫作「增」；「憎」「贈」「僧」字形相近。'],
  ['ダイエットをして、体重が三キロ【へった】。', '減った', '滅った', '感った', '域った', '數量變少用「減る」，部首是三點水，右邊有「咸」。「滅」是消失。'],
  ['そのうわさは、あっという間に町じゅうに【ひろがった】。', '広がった', '公がった', '仏がった', '払がった', '範圍擴散用「広がる」，新字體是「広」，不是繁體的「廣」。「公」「仏」「払」字形都有「ム」。'],
  ['来月から、英会話を【はじめる】つもりだ。', '始める', '姉める', '治める', '台める', '開始做某事用「始める」。「治める」讀作「おさめる」，意思是統治。'],
  ['拾った財布を交番に【とどけた】。', '届けた', '居けた', '局けた', '展けた', '把東西送交某處用「届ける」，新字體是「届」，不是繁體的「屆」。「居」「局」「展」字形相近。'],
  ['公園で虫を【つかまえた】。', '捕まえた', '補まえた', '浦まえた', '持まえた', '抓住活物用「捕まえる」。「補」「浦」與「捕」只差一個偏旁；「持」雖然也有拿住之意，但沒有這個詞。'],
  ['友達を夏祭りに【さそった】。', '誘った', '透った', '語った', '説った', '邀請別人用「誘う」。「透った」是「とおった」，「語った」是「かたった」，讀音與意思都不同。'],
  ['先約があったので、友達の誘いを【ことわった】。', '断った', '継った', '続った', '絶った', '拒絕邀約用「断る」，新字體是「断」，不是繁體的「斷」。「絶つ」讀作「たつ」，意思是斷絕。'],
  ['お年寄りに席を【ゆずった】。', '譲った', '議った', '護った', '嬢った', '把座位讓給別人用「譲る」，新字體是「譲」，不是繁體的「讓」。「議」「護」「嬢」字形相近。'],
  ['友人を家に【まねいて】、夕食を一緒に食べた。', '招いて', '拐いて', '紹いて', '昭いて', '邀請客人來家裡用「招く」，是「扌」加「召」。「紹」「昭」也有「召」，但偏旁不同。'],
  ['久しぶりに、大学時代の友人の家を【たずねた】。', '訪ねた', '防ねた', '問ねた', '探ねた', '拜訪某人或某處用「訪ねる」，左邊是「言」。「防」右邊同樣是「方」，字形相近；「問」「探」雖然和詢問、尋找有關，但都不是此詞的寫法。'],
  ['旅行の間、荷物を駅のロッカーに【あずけた】。', '預けた', '頂けた', '領けた', '順けた', '寄放東西用「預ける」。「頂」「領」「順」右邊同樣是「頁」，字形相近，要注意左邊的部件。'],
  ['祖父は庭で小さな犬を【かって】いる。', '飼って', '飾って', '飲って', '飽って', '養動物用「飼う」，部首是食字旁。「飾る」讀作「かざる」，意思是裝飾。'],
  ['電車の中で財布を【ぬすまれた】。', '盗まれた', '姿まれた', '資まれた', '盛まれた', '偷東西用「盗む」，日文新字體上半是「次」，不是繁體的「盜」。「姿」「資」同樣含有「次」，「盛」下半同樣是「皿」，字形相近但不是此詞的寫法。'],
  ['犯人は車で現場から【にげた】。', '逃げた', '挑げた', '眺げた', '跳げた', '逃走用「逃げる」，部首是「辶」。「挑」「眺」「跳」右邊都是「兆」，是最容易混淆的字。'],
  ['兄は父によく【にて】いる。', '似て', '以て', '仮て', '例て', '外貌或性格相像用「似る」，常說「似ている」。「以」是「もって」，字形接近但意思不同。'],
  ['忘れ物を取りに、急いで家に【もどった】。', '戻った', '房った', '涙った', '戸った', '回到原處用「戻る」。「房」「涙」「戸」字形都含「戸」，容易混淆；「戻」是「戸」加「大」。'],
  // ── 形容詞 ──
  ['この辞書は【あつくて】、持ち歩くのが大変だ。', '厚くて', '暑くて', '熱くて', '薄くて', '書本或布料等的厚度用「厚い」。「暑い」是天氣熱，「熱い」是物體燙；「薄い」讀作「うすい」。'],
  ['ラーメンが【あつくて】、すぐには食べられなかった。', '熱くて', '暑くて', '厚くて', '熟くて', '食物、洗澡水等溫度高用「熱い」。「暑い」只用於氣溫，不能用在食物上。'],
  ['字が【こまかくて】、読みにくい。', '細かくて', '組かくて', '紙かくて', '絹かくて', '細緻、瑣碎用「細かい」。「組」「紙」「絹」與「細」同樣是糸字旁，容易混淆。'],
  ['【はげしい】風で、傘が壊れてしまった。', '激しい', '徹しい', '撤しい', '敬しい', '程度強烈用「激しい」，部首是三點水。「徹」「撤」字形相近但意思不同。'],
  ['父は礼儀に【きびしい】人だ。', '厳しい', '険しい', '験しい', '検しい', '嚴格用「厳しい」，新字體是「厳」，不是繁體的「嚴」。「険しい」讀作「けわしい」，用於山路或表情。'],
  ['その店の場所なら、友人のほうが【くわしい】。', '詳しい', '評しい', '訴しい', '許しい', '對某事知道得很清楚用「詳しい」。「評」「訴」「許」都是言字旁，容易搞混。'],
  ['試合に負けて、とても【くやしい】。', '悔しい', '海しい', '梅しい', '侮しい', '因失敗而不甘心用「悔しい」，部首是「忄」，和「梅」「海」的右邊相同。'],
  ['みんなの前で転んで、【はずかしかった】。', '恥ずかしかった', '取ずかしかった', '耳ずかしかった', '聴ずかしかった', '覺得丟臉用「恥ずかしい」，是「耳」加「心」，送假名從「ず」開始。「取」「耳」「聴」只是字形相近。'],
  ['古い写真を見て、子どものころが【なつかしく】なった。', '懐かしく', '慣かしく', '憎かしく', '壊かしく', '令人懷念用「懐かしい」，新字體是「懐」，不是繁體的「懷」。「慣」「憎」「壊」字形相近。'],
  ['昨夜あまり寝られなくて、今日は一日【ねむい】。', '眠い', '眼い', '眺い', '民い', '想睡覺用「眠い」，部首是「目」，右邊是「民」。「眼」「眺」同樣是目字旁。'],
  ['この問題は【やさしくて】、子どもでも解ける。', '易しくて', '優しくて', '憂しくて', '楽しくて', '簡單用「易しい」。「優しい」是溫柔，不能形容問題簡單。'],
  ['この部屋は【せまくて】、大きな家具が置けない。', '狭くて', '挟くて', '峡くて', '浅くて', '空間窄小用「狭い」，新字體是「狭」，不是繁體的「狹」。「挟」「峡」字形相近；「浅」讀作「あさい」。'],
  ['靴が泥で【きたなく】なった。', '汚く', '汗く', '汁く', '洗く', '骯髒用「汚い」，新字體是「汚」，不是中文常見的「污」「汙」。「汗」「汁」字形相近。'],
  ['この辺りで雪が降るのは【めずらしい】。', '珍しい', '診しい', '沈しい', '彩しい', '稀奇罕見用「珍しい」，部首是「王」。「診」「沈」「彩」右邊的部件相似，只是字形相近。'],
  ['外が急に【さわがしく】なった。', '騒がしく', '騰がしく', '駆がしく', '騎がしく', '吵鬧用「騒がしい」，新字體是「騒」，不是繁體的「騷」。「騰」「駆」「騎」都是馬字旁。'],
  // ── 名詞 ──
  ['遠くに火事の【けむり】が見えた。', '煙', '畑', '灰', '炎', '冒出的煙用「煙」，部首是火字旁。「灰」是灰燼，「炎」是火焰，都不是煙。'],
  ['買った野菜を【ふくろ】に入れた。', '袋', '装', '袖', '衣', '裝東西的袋子用「袋」，是「代」加「衣」。「装」讀作「そう」，「袖」讀作「そで」。'],
  ['川の【きし】に座って、魚を釣った。', '岸', '岩', '崖', '峠', '河邊、海邊的邊緣用「岸」，是「山」「厂」「干」組成。「岩」是岩石，「崖」是懸崖，「峠」是山頂的隘口。'],
  ['朝早く、【みずうみ】の周りを散歩した。', '湖', '潮', '港', '池', '大型的內陸水域用「湖」。「池」讀作「いけ」，規模較小；「港」是港口。'],
  ['台風で、家の【やね】が壊れた。', '屋根', '屋棟', '屋板', '家根', '房屋頂用「屋根」，由「屋（や）」加「根（ね）」組成，要整體記。「家根」並不是標準寫法。'],
  ['事故にあったが、【いのち】は助かった。', '命', '令', '今', '念', '生命用「命」，字形可看成「令」中多了「口」。「令」少了「口」，「念」「今」只是字形相近。'],
  ['兄と弟は【なか】がよく、いつも一緒に遊んでいる。', '仲', '中', '忠', '伸', '人與人的關係用「仲」，如「仲がいい」「仲直り」。「中」讀作「なか」，是裡面，不用於關係。'],
  ['赤ちゃんの【えがお】を見ると、元気が出る。', '笑顔', '笑額', '咲顔', '笑頭', '笑臉用「笑顔」。「顔」與「額」同樣有「頁」，但「額」是額頭。「咲く」是花開。'],
  ['転んで、ひざに【きず】ができた。', '傷', '湯', '償', '像', '受傷、傷口用「傷」。「湯」讀作「ゆ」，右半部與「傷」相似，是最容易混淆的字。'],
  ['重い荷物を持ち続けて、【うで】が痛くなった。', '腕', '腰', '脳', '晩', '手臂用「腕」，部首是月字旁。「腰」讀作「こし」，「脳」是「腦」的新字體。'],
  ['みかんの【かわ】をむいて食べた。', '皮', '川', '波', '被', '水果、動物表面的皮用「皮」。「川」是河流，「波」讀作「なみ」，「被」讀作「ひ」。'],
  ['洗面所の【かがみ】で髪を直した。', '鏡', '境', '競', '鎖', '照人的鏡子用「鏡」，部首是金字旁。「境」「競」右邊相同，但部首不同。'],
  ['朝は【きり】が深くて、前がよく見えなかった。', '霧', '露', '霜', '雷', '空氣中的水滴形成的霧用「霧」。「露」是露水，「霜」是霜，「雷」是雷，都是雨字頭的天氣用字。'],
  ['母の誕生日に【おくりもの】を選んだ。', '贈り物', '送り物', '増り物', '憎り物', '送給對方的禮物用「贈り物」，部首是貝字旁。「送る」是寄送或送行，表示禮物的「おくりもの」標準寫法是「贈り物」。「増」「憎」字形相近。'],
  ['友人から、結婚するという【しらせ】が届いた。', '知らせ', '失らせ', '短らせ', '和らせ', '通知、消息用「知らせ」，由動詞「知らせる」轉成名詞，要加送假名「らせ」。「失」「短」都和「知」中的「矢」相關，但並沒有這種寫法。']
]);
